                    if tuple(b_rf) in permutations(a_rf):
                        if not (no_ident and a_rf == b_rf):
                            if not (no_ident and len(a_rf) == 0):
                                yield S
                        return
                    else:
                        return

            yield from lany(inner_eq(b_rf, a_type(i)) for i in a_perms)(S)

        elif isinstance(b_rf, Sequence) and not isinstance(b_rf, (str, bytes)):

            b_type = type(b_rf)
            b_perms = permutations(b_rf)

            if no_ident:
                if isground(a_rf, S) and isground(b_rf, S) and a_rf == b_rf:
                    b_perms = skip_identity_perm(b_perms, b_rf)
                    if b_perms is None:
                        return

