def permuteo(a, b, inner_eq=eq, default_ConsNull=list, no_ident=False):
    """Construct a goal asserting equality or sequences under permutation.

    For example, (1, 2, 2) equates to (2, 1, 2) under permutation
    >>> from kanren import var, run, permuteo
    >>> x = var()
    >>> run(0, x, permuteo(x, (1, 2)))
    ((1, 2), (2, 1))

    >>> run(0, x, permuteo((2, 1, x), (2, 1, 2)))
    (2,)
    """

    def permuteo_goal(S):
        nonlocal a, b, default_ConsNull, inner_eq

        a_rf, b_rf = reify((a, b), S)

        a_len = length_hint(a_rf, -1)
        b_len = length_hint(b_rf, -1)
        if a_len >= 0 and b_len >= 0 and a_len != b_len:
            return

        # Handle empty sequence cases with no_ident properly
        if no_ident:
            if a_len == 0 and b_len == 0:
                return
            if (a_len == 0 and b_len > 0) or (b_len == 0 and a_len > 0):
                return

        def skip_identity_perm(perms, original_seq):
            try:
                first_perm = next(perms)
            except StopIteration:
                return None
            # If first_perm is identity, skip it (do not yield it)
            if first_perm == tuple(original_seq):
                return perms
            # Else, yield first_perm and then the rest
            return (perm for perm in (first_perm,) + tuple(perms))

        # Helper to check if sequences are equal or contain variables
        def is_equal_or_vars(seq1, seq2):
            if len(seq1) != len(seq2):
                return False
            for x, y in zip(seq1, seq2):
                if isvar(x) or isvar(y):
                    # Cannot determine definitively, treat as not equal
                    return False
                if x != y:
                    return False
            return True

        if isinstance(a_rf, Sequence) and not isinstance(a_rf, (str, bytes)):

            a_type = type(a_rf)

            a_perms = permutations(a_rf)

            if no_ident:
                # Skip identity permutation only if a_rf and b_rf are ground and equal
                if isground(a_rf, S) and isground(b_rf, S) and a_rf == b_rf:
                    a_perms = skip_identity_perm(a_perms, a_rf)
                    if a_perms is None:
                        return

            if isinstance(b_rf, Sequence) and not isinstance(b_rf, (str, bytes)):

                b_type = type(b_rf)

                if a_type != b_type:
                    return

                if no_ident:
                    if isground(a_rf, S) and isground(b_rf, S) and a_rf == b_rf:
                        return

                try:
                    cntr_a, cntr_b = Counter(a_rf), Counter(b_rf)
                    rdcd_a, rdcd_b = cntr_a - cntr_b, cntr_b - cntr_a

                    if len(rdcd_a) == len(rdcd_b) == 0:
                        if not (no_ident and isground(a_rf, S) and isground(b_rf, S) and a_rf == b_rf):
                            # Do not yield the empty tuple when no_ident is True and sequence is empty
                            if not (no_ident and len(a_rf) == 0):
                                # Special fix: when yielding empty tuple, yield nothing for no_ident==True
                                if not (no_ident and len(a_rf) == 0):
                                    yield S
                        return
                    elif len(rdcd_a) < len(cntr_a):
                        a_rf, b_rf = tuple(rdcd_a.elements()), b_type(rdcd_b.elements())
                        a_perms = permutations(a_rf)
                        if no_ident:
                            if isground(a_rf, S) and isground(b_rf, S) and a_rf == b_rf:
                                a_perms = skip_identity_perm(a_perms, a_rf)
                                if a_perms is None:
                                    return

                except TypeError:
                    pass

                if inner_eq == eq and isground(a_rf, S) and isground(b_rf, S):
                    if tuple(b_rf) in permutations(a_rf):
                        if not (no_ident and a_rf == b_rf):
                            if not (no_ident and len(a_rf) == 0):
                                yield S
                        return
                    else:
                        return

            yield from lany(inner_eq(b_rf, a_type(i)) for i in a_perms)(S)

        elif isinstance(b_rf, Sequence) and not isinstance(b_rf, (str, bytes)):

            b_type = type(b_rf)
            b_perms = permutations(b_rf)

            if no_ident:
                if isground(a_rf, S) and isground(b_rf, S) and a_rf == b_rf:
                    b_perms = skip_identity_perm(b_perms, b_rf)
                    if b_perms is None:
                        return

            yield from lany(inner_eq(a_rf, b_type(i)) for i in b_perms)(S)

        else:

            a_itero_g = itero(
                a_rf, nullo_refs=(b_rf,), default_ConsNull=default_ConsNull
            )

            for S_new in a_itero_g(S):
                a_new = reify(a_rf, S_new)
                a_type = type(a_new)
                a_perms = permutations(a_new)

                if no_ident:
                    if isground(a_new, S_new) and isground(b_rf, S_new) and a_new == b_rf:
                        a_perms = skip_identity_perm(a_perms, a_new)
                        if a_perms is None:
                            return

                yield from lany(inner_eq(b_rf, a_type(i)) for i in a_perms)(S_new)

    return permuteo_goal


